public abstract class Exporter
{
    protected Exporter(string extension) => Extension = extension;
    public string Extension { get; }

    public string Export(Report r) => Header() + Body(r); // template method
    protected virtual string Header() => "";
    protected abstract string Body(Report r);            // musi być nadpisana
}

public sealed class CsvExporter() : Exporter(".csv")
{
    protected override string Body(Report r) => string.Join(';', r.Values);
}

